package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Entities_unescape_TriageGen0Test {

    private Entities entities;
    private StringWriter writer;

    @Before
    public void setUp() {
        entities = new Entities();
        writer = new StringWriter();
    }

    @Test
    public void testUnescape_NoAmpersand() throws IOException {
        entities.unescape(writer, "hello world");
        assertEquals("hello world", writer.toString());
    }

    @Test
    public void testUnescape_NoSemicolon() throws IOException {
        entities.unescape(writer, "hello &world");
        assertEquals("hello &world", writer.toString());
    }

    @Test
    public void testUnescape_AmpersandBeforeSemicolon() throws IOException {
        // Tests the logic: if (amphersandIdx != -1 && amphersandIdx < semiColonIdx)
        entities.unescape(writer, "hello &foo&bar;");
        assertEquals("hello &foo&bar;", writer.toString());
    }

    @Test
    public void testUnescape_NamedEntitySuccess() throws IOException {
        entities.addEntity("lt", '<');
        entities.unescape(writer, "a &lt; b");
        assertEquals("a < b", writer.toString());
    }

    @Test
    public void testUnescape_NamedEntityFailure() throws IOException {
        // Unknown entity should be written as-is
        entities.unescape(writer, "a &unknown; b");
        assertEquals("a &unknown; b", writer.toString());
    }

    @Test
    public void testUnescape_EmptyEntity() throws IOException {
        entities.unescape(writer, "a &; b");
        assertEquals("a &; b", writer.toString());
    }

    @Test
    public void testUnescape_DecimalEntitySuccess() throws IOException {
        entities.unescape(writer, "&#60;");
        assertEquals("<", writer.toString());
    }

    @Test
    public void testUnescape_DecimalEntityFailure() throws IOException {
        entities.unescape(writer, "&#abc;");
        assertEquals("&#abc;", writer.toString());
    }

    @Test
    public void testUnescape_HexEntityUpper() throws IOException {
        entities.unescape(writer, "&#X3C;");
        assertEquals("<", writer.toString());
    }

    @Test
    public void testUnescape_HexEntityLower() throws IOException {
        entities.unescape(writer, "&#x3c;");
        assertEquals("<", writer.toString());
    }

    @Test
    public void testUnescape_HexEntityFailure() throws IOException {
        entities.unescape(writer, "&#XG1;");
        assertEquals("&#XG1;", writer.toString());
    }

    @Test
    public void testUnescape_DecimalEntitySingleDigit() throws IOException {
        // entityContentLen > 1 check (e.g., "&#1;")
        entities.unescape(writer, "&#1;");
        assertEquals(String.valueOf((char)1), writer.toString());
    }

    @Test
    public void testUnescape_DecimalEntityNoDigits() throws IOException {
        // Tests the case where entityContentLen > 1 but no digits follow #
        entities.unescape(writer, "&#;"); 
        assertEquals("&#;", writer.toString());
    }

    @Test
    public void testUnescape_MixedContent() throws IOException {
        entities.addEntity("quot", '"');
        entities.unescape(writer, "text &quot; &amp; &#60; &#x41;");
        // Note: &amp; is not explicitly in a custom map, but if entityValue returns -1, it prints as is.
        // However, if we assume standard behavior or if we want to test the loop:
        assertEquals("text \" &amp; < A", writer.toString());
    }

    @Test
    public void testUnescape_ComplexNestedStructure() throws IOException {
        // Tests the loop and index jumping logic
        entities.addEntity("a", 97);
        entities.unescape(writer, "&a;&a;&a;");
        assertEquals("aaa", writer.toString());
    }

    @Test
    public void testUnescape_TrailingAmpersand() throws IOException {
        entities.unescape(writer, "test &");
        assertEquals("test &", writer.toString());
    }
}
